 "content": "def transform(grid):
    # Determine the repeating motif by reading the colored diagonal bands.
    # Nonzero cells on lines of constant (column-row) represent successive
    # entries of the encoded tile; use their earliest occurrences in scan order.
    n = len(grid)
    bands = {}
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v:
                bands.setdefault(c-r, v)
    offsets = sorted(bands)
    seq = [bands[d] for d in offsets]
    if not seq:
        # Solid horizontal bands: preserve the interior and extend boundary colors.
        out = [row[:] for row in grid]
        for c in range(len(grid[0])):
            if out[0][c] == 0:
                out[0][c] = next((v for row in grid for v in row if v), 0)
            if out[-1][c] == 0:
                out[-1][c] = next((v for row in reversed(grid) for v in row if v), 0)
        return out
    return [[seq[(r+c) % len(seq)] for c in range(len(grid[0]))] for r in range(n)]

